"""Backend-specific modeling guidance; no physical or delivery approval."""


def plan(mechanisms, objects):
    result={}
    for obj,spec in mechanisms.get('objects',{}).items():
        if obj not in objects:continue
        for name,body in spec.get('links',{}).items():
            if body.get('kind')!='cloth':continue
            backend=body.get('backend','particle')
            result[f'{obj}/{name}']={
                'backend':backend,
                'particle_coverage_required':backend=='particle',
                'particle_initial_envelopes_required':backend=='particle',
                'finite_sheet_clearance_required':True,
                'mesh_resolution_basis':('Native material and triangle-contact convergence; do not inherit particle sphere-coverage refinement.'
                    if backend=='surface_fem' else 'Native material response and actual particle contact coverage, including rigid and self contact.'),
                'next_stage_order':['source_relative_orientation_and_full_material_layout',
                    'backend_material_dissipation_and_required_contact_controls',
                    'physically_admissible_initial_state','unforced_state_and_mechanism_release',
                    'requested_interaction_and_causal_controls','export_reload_and_delivery'],
                'failed_initial_state_action':'Review support, hidden packing, initial elastic energy and contact representation before changing constitutive parameters.',
                'unsupported_required_contact_action':'Pause full task trials on that backend. Reproduce the missing contact effect in an independent matched control; qualify an alternative representation before switching. Do not remove a physically required effect to obtain a task pass.',
                'numerical_profile_policy':'Qualify the actual solver, timestep, iteration budget, mesh and coordinate precision together. More substeps or iterations can destroy a small signal through rounding. A failed profile does not disqualify every configuration of the native representation. Compare gravity-driven contact controls when a nodal-force or mass adapter is unverified, then verify mass/contact response on the actual material mesh.',
                'contact_profile_readback':'Check effective stage contact offsets and iteration settings after applying material priors, before matching a control. Preserve explicit numerical rest padding separately from physical thickness across prior cases; requested configuration alone is not a readback.',
                'initial_collision_margin_review':'Check the initial posed and natural-reference geometry against the actual numerical rest/contact filter distances as well as physical thickness. Increasing collision margins around an existing folded pose can create artificial preload and startup recoil; rebuild or physically prepare the pose instead of interpreting that recoil as material elasticity.',
                'whole_shape_contact_isolation':'A flat contact coupon does not qualify a folded whole sheet. If preparation develops unexplained motion, compare the same whole mesh, intrinsic chart and native material with zero gravity, no fixtures or rigid partners, first without and then with self contact. Retain the actual warmup state, material strain, motion and energy diagnostics. If only self contact causes growth, review local bend radius and numerical envelope conflicts before tuning damping. For hidden preparation proposals, prefer an admissible fold geometry; do not change intrinsic dimensions, inflate physical thickness or filter distant plies to hide the failure.',
                'free_release_numerics_review':'Use check_surface_release.py for complete source-mesh surface-FEM isolation without rigid actors or attachments; check_particle_release.py retains its independent particle path. Record native warmup displacement, COM, momentum and kinetic energy alongside intrinsic strain. Automatic per-node speed limiting can inject a net momentum defect in a highly strained pose: compare a declared explicit speed bound on the same mesh/profile before interpreting bulk drift as physical elasticity. A smaller COM drift does not remove internal unfolding or qualify the changed profile for contact tasks. Keep matched contact and export/reload checks before adoption.',
                'compliant_contents_capability':'If loose contents supply retention pressure, verify the actual soft-soft pair on the installed native APIs before selecting a backend. check_compliant_sheet_contact.py uses explicit beta volume FEM and surface FEM, without cloth/volume pins, under a declared platen and finite diagnostic loads. A legacy volume capability must not be borrowed for beta volume, or conversely. Require light-load hold, finite extraction, matched zero friction and no-preload controls; permanent jamming or contact strain cannot establish realistic stock compliance. Numerical rest offsets are not physical contents compression. Coupon fixtures never approve the full source state or a grasp.',
                'particle_filter_review':'A declared restPoints array or selfCollisionFilter flag does not prove the installed engine uses the intended material-neighbour filter. Check actual pair response and cooking provenance, especially after baking a folded candidate. Reopening the exported asset must preserve nonlocal layer contact; an authored chart, an initial separation screen or a flat coupon alone cannot establish this.',
                'loaded_fold_screen':('Use check_particle_release.py with --shape accordion --size-m 0.08 --prestrain 0 --loaded-fold --seconds 0.9 and the actual native profile to screen coupled bending, finite loading and self contact independently of any video. Supply a diagnostic gravity explicitly. This synthetic screen grants no source, task, material or export approval and cannot replace whole-sheet tests.'
                    if backend=='particle' else None),
                'material_inference_policy':'A prior-only nominal value is not an identified material. After geometric and numerical validity, compare bounded material hypotheses against independent source passive shape and observed motion; retain uncertainty. Task success alone cannot identify stiffness, mass or friction.',
                'particle_damping_review':'Per-spring damping depends on actual nodal mass, spring constants and material sampling. Do not copy a continuum damping coefficient or an unqualified lattice coefficient between resolutions. Compare loaded zero-friction controls: discrete contact geometry and normal corrections can create resistance even when the authored friction is zero. Keep failed baselines and qualify the actual profile before hand acceptance.',
                'release_review':'Distinguish membrane stretch, bending stiffness, natural curvature, dissipation and contact release. Compare matched zero/material-damping controls and source motion; a stiffness test with damping disabled does not validate recoil. Estimate initial stored bending energy before stiffening a tightly folded sheet.',
                'natural_fold_orientation_review':'Inspect natural_fold_orientation in the initial release diagnostic. A reflected material frame reverses signed creases even with unchanged intrinsic dimensions. Explain any flagged mismatch using construction provenance or actual preload; never silently copy the current contact-imposed pose into the natural reference. Verify the installed native reference feature with positive and reflected controls.',
                'material_sweep_construction':'Use cloth_curve.sweep for width/length/thickness charts along an XZ curve, or prove the local placement frame has determinant +1. A planar left normal combined with world-Y width reflects the chart; edge lengths alone cannot detect this error. Keep initial contacts and material history independently checked.',
                'initial_clamp_review':'A geometrically closed assembly or a declared support relation does not prove loaded contact. Verify the actual passive hold, then release the real mechanism and test the required interaction. Distinguish missing closure load, artificial prestrain and contact solver failure before changing material parameters.',
                'preparation_phase_conditions':'Before a potentially compressive or obstructing preparation motion, declare a preparation.checkpoints entry with name, time_s, conditions and basis. Reuse actual material_support, container_state, interfaces or maximum_hinge_angle_rad conditions as appropriate. Stop the trial before further commands if the current native condition fails; retain the failed state. A timed trajectory is not evidence that the material reached its intended support. Checkpoint passes do not replace released-state, source or task acceptance.',
                'phase_condition_observable':'Choose the actual observable for each mechanism phase. A changed support state can let retained material arch above the rim; a final-state below-rim fraction is not automatically a valid preparation condition. Distinguish outside material from the sum above/inside the opening, inspect actual end tracking/support, then enforce the original closed-state insertion/support after closure and full force release. Keep failed historical conditions and every physical contact limit unchanged.',
                'packing_aperture_and_feed':'If a soft insert obstructs closure, first isolate the unchanged rigid assembly without the soft object. When empty closure works, review packing and placement instead of changing the rigid shapes or motor limits. Open the real mechanism enough to clear the preparation region, allow the free end to feed, and guide the intended inner material below the closing path with finite forces. A clear target-centre path does not prove that adjacent folds fit; inspect the complete connected neighbourhood, available material length and held regions. Use reported crossing locations in the original material chart to distinguish a collapsed supported tail from a jam beside the moving patch; locations alone do not establish causality. Holding both ends at an incompatible pose can prevent redistribution. Check actual pre-closure placement, then real closure, complete force release, retained source support and a fresh unforced rebuild; packing fixtures never enter the task.',
                'resting_support_review':'above_unthreaded proves routing only. Inspect its support-gap distribution and the actual contacting material region; a hidden end several millimetres above a tray is not established support. Compare alternative supported full-sheet packing, retaining intrinsic size and mass, before increasing friction or stiffness.',
                'guide_frame_coherence':'When a preparation region turns, added guide patches must share the intended proper frame and retain layer ordering. Check relative source/target offsets as well as initial frames and rigid clearance: independently translated targets can coalesce distinct folds. guide_frames.paths supplies coherent rotating/translated targets with an explicit interpolation-chord bound. This is a finite-force construction proposal, never a rigid cloth patch; full native material/self/solid checks and complete helper release remain required.',
                'friction_pocket_review':'A sheet retained between contents and a container wall requires actual normal preload from resolved packing, bending or compressible contents. A narrow gap alone does not establish friction. Inventory contents separately from the shell with explicit material and rigidity uncertainty; a fused rigid fill is only a declared control approximation until its task-relevant compliance and occupied space are justified. Record new user-proposed hidden routes as hypotheses, preserving excluded holes and detached topology. Compare light-load retention and finite-load extraction with matched zero-friction and unloaded-gap controls on the same material/profile. Fixed fixtures and artificial coupon loads cannot approve the whole sheet: rebuild, release all helpers, then check the actual closed/open source state, accessibility, extraction, and export reload.',
                'insertion_depth_review':'Measure below-rim material separately from material above the opening. Report opening-column occupancy, actual below-rim area and insertion depth; occupancy alone does not establish support. Compare source-consistent hidden placements with the same intrinsic shape, mass and material before changing constitutive parameters. Never move a tested cloth through solids or overwrite its native state to make a grasp work.',
                'feed_placement_proposal':'If insufficient insertion causes slip, vary the hidden placement before changing material. preparation_geometry.support_slide proposes finite guide paths for an unchanged selected patch over actual support triangles, rejecting sampled holes, boundaries and obstructing steps. Infer the feed direction from the connected sheet and support, not a universal radial rule. Feed while the opening permits movement, close before withdrawing guides, then measure actual insertion, original support and retention after all tools are released. Preserve the complete material and visible source conditions; targets are not measured material motion or task approval.',
                'direct_placement_proposal':'Initial reconstruction does not require replaying a manufacturing/packing history. Prefer a directly authored source-consistent deeper placement when physical preparation loses material before feeding it. cloth_feed.redistribute changes the internal path at fixed longitudinal arc distances while preserving the supported spine end and shortening the exposed free end. along_spine supports explicit bounded tail continuation; along_columns requires complete rectangular columns. A clipped material boundary is not the drape endpoint. All are offline proposals requiring independent material-budget, self/solid, support, source and fresh Blender/native checks. Never write these positions into a running task.',
                'preclosure_motion_review':'Default top-down cloth pinch to open approach, open descent, actual capture-pose check, then stationary closure. Check open descent and the full closing path against rigid geometry. Use actual open joints and actual wrist/material poses at the transition, not elapsed time or commanded height. A failed readiness check is a targeting/placement diagnostic, not evidence for changing cloth stiffness or friction. Preserve explicit coupled mode and exact matched-control replay when that interaction is required.',
                'pinch_contact_review':'A closing-force cap does not establish sustained preload. Qualify the actual tool/contact representation on an independent interior material pinch with stationary loaded hold and matched zero-friction replay before blaming task cloth properties. Read back native friction and distinguish query contact range from the unchanged penetration limit. Short upward motion or proximity alone is not a grasp. On folded sheets, the two fingers may contact distinct intrinsic regions of one connected sheet; retain source indices, interior boundaries and actual per-finger retention rather than requiring one arbitrary small disk.',
                'assay_order':'Check complete native initial-state and early-release material/self/solid contact before tuning a manipulation. A conservative thickness failure may receive the shared local-bend certificate, but nonlocal layers remain failures. Default asset contact tests stop; continuing a failed thickness screen is an explicit diagnostic only. Refine support, rest-reference filtering, numerical padding and matching source geometry before changing material or grasp force. A passing small coupon does not qualify a dense folded whole sheet.',
                'initial_metric_review':'After material resampling, compare authored and native-t0 intrinsic edges, principal strain and release-energy diagnostics. Approximate final response does not explain unexplained initial preload. Distinguish intended, source-supported prestress from transfer/interpolation errors; preserve the material chart and use bounded geometry projection plus a fresh Blender rebuild where necessary. Recheck source geometry, actual support, rest filtering and native release before another grasp.',
                'closed_contact_state':'A source-described closed clamp must actually retain its loose material after preparation forces are removed. A small joint angle is not proof of closure contact. Use explicit container/support/interface release conditions and source checks, including before the manipulation. Finite existing-joint actuation may prepare geometry; clear its native gains/effort, rebuild through Blender and rerun unforced checks. Never export a helper drive, weld or cloth pin as the clamp mechanism.',
                'surface_padding_proposal':('Use surface_contact_profile.padding_proposal only with a separated native gap failure, explicit numerical-padding budget and witnessed rest-pair visibility. Preserve physical thickness and all gates, check/prepare the new rest envelope, then qualify matching native controls; it never approves geometry or the task.' if body.get('backend','particle')=='surface_fem' else None),
                'packing_footprint_review':'Compare the complete folded cross-section with the actual partial support before native preparation. preparation_geometry.footprint_hull_placement can reject a footprint that cannot fit even the outer hull without changing intrinsic dimensions. A hull fit is only a proposal screen: actual holes, end-band contact, above-unthreaded routing, full material validity and released native behavior still need independent checks.',
                'perforated_support_placement':'For a retained end placed on a perforated or partial planar tray, assets.planar_support_placement.surface_placement searches translations against the union of the actual support triangles and their hole boundaries. Retain the bounded search and numerical-envelope results. A feasible outer hull is insufficient; never fill the aperture in collision geometry. This is a construction proposal only, not loaded contact or source/task acceptance.',
                'construction_numerics_scope':'Expensive fine-contact meshes may use offline preparation or explicit diagnostic construction numerics to propose geometry. Preserve every failed/approximate metric and the actual preparation profile; use geometry_seed with fresh Blender rebuilding, never relabel such a trajectory as qualified material or task evidence. Before acceptance, run fresh unforced/source/task and export-reload checks with the actual matching qualified numerical profile. An inferred preparation history is not itself the requested task.',
                'orientation_review':'Use orientation_review with primary-scene calibrated views and independent link masks to check direction relative to the rigid assembly. Also compare free-flap tilt and support state. Supplemental manipulation does not silently replace the initial scene arrangement. Rotation proposals preserve the material metric but require a new full contact check.',
                'repeated_local_repair_failure_action':'Reconsider the packing hypothesis and solver constraint formulation; do not repeat smaller patches indefinitely.',
                'continuum_prestrain_objective':'For continuum sheets, cloth_project --objective triangle_metric resolves both material directions and shear with area-weighted metric residuals. Narrow triangles can have small edge RMS but substantial principal strain. Retain the existing edge method and all independent geometry/material/support guards; judge actual principal strain and stored energy before native release.',
                'initial_equilibrium_target':'Construct the articulation/contact state specified by the input. Temporary bounded setup tools and real closure motion require actual checkpoints and complete release; preserve original material references, rebuild, and revalidate initial state, opening retention and the requested contact task afresh.',
                'experimental_backend_policy':'Keep research separate until constitutive response, dissipation, contacts and export/reload are demonstrated. A contact coupon alone cannot switch the production route.',
                'control_runtime_parity':'Use the same authoring and read back solver, timestep, iterations and external-force iteration settings in controls and task scenes. Diagnose a failed elastic response with an independent known SI spring before changing material constants. A single spring pass does not qualify a shell or attachment.',
                'whole_sheet_timestep_convergence':'Coupon success does not qualify a full folded sheet. Compare identical geometry/material at finer native clocks when release creates thin-layer crossings. Read actual nodal velocities and time_resolution; sampled travel/thickness ratios are diagnostics, never CCD or acceptance. Fine-clock construction must retain complete material/volume references, then pass fresh unforced/source/task/export checks at the selected qualified production profile. Positive volume Jacobians also require actual soft-boundary versus rigid-container penetration checks.',
                'acceptance_policy':'Default to task_and_semantics for flexible response: retain exact local shape, strain and material-response errors as diagnostics; require semantic structure, plausible material behavior, valid contacts/stability and the actual requested task. Use quantitative mode for explicitly required precise response. Rigid shape/scale precision is unchanged; a rigid substitute is not exempt.',
                'task_approved':False}
    return result
